                        "text": "This one gets every detail right: a bright green cap with the classic \"L\" patch, bushy embroidered eyebrows, big blue eyes, and a thick black mustache stitched with care. He's dressed in a blue-and-white striped shirt under denim-blue overalls with yellow button details, finished off with soft pink ears and rosy round cheeks that give him real character."
