                        "text": "The plush body is well-filled and holds its shape through daily hugs, with wide white-gloved hands and feet that let him sit upright on a shelf, bed, or gaming desk without support. Every seam is neatly finished, and there's nothing hard, sharp, or loose anywhere on him — just safe, soft plush from cap to toe."
